async function refreshWorldBroadcasts(){if(document.hidden)return;if(!state.centralPlayerId)return;try{const d=await centralDirectoryRequest('/api/world-announcements');state.worldBroadcastIds=state.worldBroadcastIds||[];let changed=false;for(const w of [...d.announcements].reverse()){if(state.worldBroadcastIds.includes(w.id))continue;state.worldBroadcastIds.push(w.id);state.news.unshift({text:w.text,type:'good',category:'GAME_UPDATES',tick:state.tick,at:w.at,worldAnnouncement:w,anonymous:true});changed=true;}if(changed){save();renderNews();}}catch{}}
function queueEarthSalvage(report){state.pendingEarthSalvage=state.pendingEarthSalvage||[];if(!state.pendingEarthSalvage.some(r=>r.id===report.id))state.pendingEarthSalvage.push(copy(report));save();settleEarthSalvage();}
let earthSalvageBusy=false;async function settleEarthSalvage(){if(earthSalvageBusy||!state.centralPlayerId)return;earthSalvageBusy=true;try{for(const r of [...state.pendingEarthSalvage||[]]){try{const result=await centralDirectoryRequest('/api/earth-salvage',{...r,generation:state.centralResetGeneration||0});state.pendingEarthSalvage=state.pendingEarthSalvage.filter(x=>x.id!==r.id);const live=state.news.find(n=>n.battleReport?.id===r.id)?.battleReport;if(live?.earthSalvage){live.earthSalvage.status='Credited to Earth owner';live.salvage=result.award;}await refreshSharedPlanets();save();}catch(e){if(e.status===400||e.status===403){state.pendingEarthSalvage=state.pendingEarthSalvage.filter(x=>x.id!==r.id);save();}break;}}}finally{earthSalvageBusy=false;}}
function enforceSpecialWorldTheme(){const skin=state.userSettings?.skinRace;if(['SilverWorld','BorgWorld','UndineWorld','LegendaryWorld','UltimateWorld','Unimatrix999World'].includes(skin)&&!visibleWorldThemes().some(([id])=>id===skin)){state.userSettings.skinRace='Neutral';document.body.dataset.skin='Neutral';}}
setTimeout(()=>{state.galaxyBrowserVisited=false;enforceSpecialWorldTheme();refreshWorldBroadcasts();settleEarthSalvage();},2500);setInterval(()=>{enforceSpecialWorldTheme();refreshWorldBroadcasts();settleEarthSalvage();},30000);

function decorateWorldStats(){const t=planetTypeFor(state);for(const id of ["page-fleets","page-battleCalculator","page-bcalc","page-universe","page-galaxy"]){const page=document.getElementById(id);if(!page)continue;let box=page.querySelector(".world-feature-strip");if(!box){box=document.createElement("section");box.className="world-feature-strip";page.prepend(box);}box.innerHTML='<img src="/assets/planets/'+esc(t.id)+'.svg" alt="'+esc(t.name)+'"><div><b>'+esc(t.name)+' · '+esc(t.rarity)+'</b><small>Habitability '+t.habitability+'% · Population growth '+(t.growthPercent>=0?"+":"")+t.growthPercent+'% · Fleet travel '+(t.travelEtaBonus||0)+' tick · Bonus salvage '+(t.salvageBonusPercent||0)+'%</small></div>';}}setTimeout(decorateWorldStats,2500);setInterval(decorateWorldStats,15000);
